/* prog22_snake_camel_convert – reconstructed from the obfuscated binary
 *
 * The original binary expects exactly two command‑line arguments:
 *   1. a mode string – either "to_camel" or "to_snake"
 *   2. the input string to be converted
 *
 * Behaviour:
 *   * If the argument count is less than 3 → prints "USAGE"
 *   * If the mode is not one of the two supported strings → prints "INVALID_MODE"
 *   * Otherwise it converts the input:
 *        – "to_camel" : snake_case  → camelCase
 *        – "to_snake" : camelCase   → snake_case
 *   * The result is printed with a trailing newline (via puts).
 *
 * The implementation below follows the same observable behaviour while
 * ignoring the internal obfuscation that the original binary used.
 */

#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define OUT_MAX 4096   /* more than enough for the test cases */

/* Convert a snake_case string to camelCase.
 * The first word stays lower‑case; each following word starts with an
 * upper‑case letter. Underscores are removed.
 */
static void to_camel(const char *src, char *dst)
{
    int capitalize = 0;   /* flag: next alphabetic character should be upper case */
    while (*src) {
        if (*src == '_') {
            capitalize = 1;          /* next character will be capitalised */
        } else {
            if (capitalize && islower((unsigned char)*src)) {
                *dst++ = (char)toupper((unsigned char)*src);
            } else {
                *dst++ = *src;
            }
            capitalize = 0;
        }
        ++src;
    }
    *dst = '\0';
}

/* Convert a camelCase string to snake_case.
 * Upper‑case letters become lower‑case and are preceded by an underscore,
 * except when they are the very first character.
 */
static void to_snake(const char *src, char *dst)
{
    int first = 1;        /* true while we are at the first character */
    while (*src) {
        if (isupper((unsigned char)*src)) {
            if (!first) {
                *dst++ = '_';
            }
            *dst++ = (char)tolower((unsigned char)*src);
        } else {
            *dst++ = *src;
        }
        first = 0;
        ++src;
    }
    *dst = '\0';
}

int main(int argc, char **argv)
{
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }

    const char *mode = argv[1];
    const char *input = argv[2];
    char output[OUT_MAX];

    if (strcmp(mode, "to_camel") == 0) {
        to_camel(input, output);
        puts(output);
    } else if (strcmp(mode, "to_snake") == 0) {
        to_snake(input, output);
        puts(output);
    } else {
        puts("INVALID_MODE");
    }

    return 0;
}
